import{_ as i}from"./chunks/KEITH_RICHARDS_MESA_03.BE98nuu1.js";import{o as n,c as r,a0 as t,j as a,t as l,p as d}from"./chunks/framework.L_oL6aia.js";const c={class:"rock-card-contact"},m={class:"rock-copy-email-wrapper"},f=JSON.parse(`{"title":"La Historia del '78 al '81: Cómo los Stones conocieron a Mesa/Boogie","description":"","frontmatter":{},"headers":[],"relativePath":"es/history-mesa-stones.md","filePath":"es/history-mesa-stones.md"}`),u={name:"es/history-mesa-stones.md"},y=Object.assign(u,{setup(p){const o=d("Copiar Correo");function s(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),o.value="¡Copiado!",setTimeout(function(){o.value="Copiar Correo"},2e3)}return(g,e)=>(n(),r("div",null,[e[3]||(e[3]=t('<h1 id="la-historia-del-78-al-81-como-los-stones-conocieron-a-mesa-boogie" tabindex="-1">La Historia del &#39;78 al &#39;81: Cómo los Stones conocieron a Mesa/Boogie <a class="header-anchor" href="#la-historia-del-78-al-81-como-los-stones-conocieron-a-mesa-boogie" aria-label="Permalink to &quot;La Historia del &#39;78 al &#39;81: Cómo los Stones conocieron a Mesa/Boogie&quot;">​</a></h1><p><strong>Archivo Histórico y Notas de Sonido · Main St Audio Labs</strong></p><hr><img src="'+i+'" alt="Keith Richards con su Mesa Boogie Mark I" style="max-height:400px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:6px;"><p>A finales de la década de 1970, mientras los Rolling Stones se preparaban para su gira <em>Some Girls</em> y una serie de sesiones de estudio legendarias, una pieza crítica de su icónico tono de guitarra se forjó, no en una enorme fábrica de Londres, sino en un pequeño taller californiano. La historia de cómo Keith Richards y los Stones adquirieron sus legendarios amplificadores Mesa/Boogie Mark I de 100W es un capítulo fascinante en la historia del rock.</p><h2 id="el-nacimiento-del-boogie" tabindex="-1">El Nacimiento del Boogie <a class="header-anchor" href="#el-nacimiento-del-boogie" aria-label="Permalink to &quot;El Nacimiento del Boogie&quot;">​</a></h2><p>La historia comienza con Randall (Randy) Smith, quien empezó modificando pequeños combos Fender Princeton en la parte trasera de Prune Music, una tienda en Lagunitas / Mill Valley, California. Smith tomaba estos modestos amplificadores de práctica y los potenciaba, introduciendo enormes transformadores Bassman y circuitos de alta ganancia.</p><p>La leyenda cuenta que cuando Carlos Santana tocó uno de estos primeros prototipos modificados, exclamó la famosa frase: <em>&quot;Man, that little thing really boogies!&quot;</em> (¡Hombre, esa cosita realmente rockea/boogies!)—y así nació el nombre Mesa/Boogie.</p><p>Estos primeros amplificadores Mark I fueron revolucionarios: empacaban la asombrosa cantidad de 100 vatios de potencia RMS en un formato compacto 1x12&quot;. Para manejar esta inmensa potencia sin explotar, Smith los cargaba con altavoces de servicio pesado, más notablemente el Electro-Voice EVM-12L o el Altec 417, alojados en gabinetes de madera dura bellamente elaborados. El Mark I no era un amplificador de canales intercambiables en el sentido moderno; en cambio, contaba con dos entradas. La Entrada 1 ofrecía cuatro etapas de ganancia impulsadas por 12AX7 para tonos solistas abrasadores, mientras que la Entrada 2 omitía una etapa para un tono rítmico más limpio, tipo &quot;Fender modificado&quot;.</p><h2 id="la-llamada-de-ian-stewart" tabindex="-1">La Llamada de Ian Stewart <a class="header-anchor" href="#la-llamada-de-ian-stewart" aria-label="Permalink to &quot;La Llamada de Ian Stewart&quot;">​</a></h2><p>A principios de 1977, los Rolling Stones se preparaban para sus primeras fechas en clubes en 14 años: los famosos shows de El Mocambo en Toronto, Canadá, que eventualmente compondrían el lado tres del álbum <em>Love You Live</em>. Los rumores de estos amplificadores californianos increíblemente fuertes y sensibles al tacto habían llegado al campamento de los Stones.</p><p>Según Randy Smith, la conexión comenzó con una llamada telefónica sorprendente. Como recordó Smith: <em>&quot;En ese momento, construir amplificadores era una industria artesanal y yo hacía todo. Así que, levanté el teléfono y era [el pianista de los Stones] Ian Stewart. Me dijo: &#39;Estamos interesados en probar un Boogie.&#39; Habían escuchado mucho sobre ellos y me preguntó si enviaría algunos. Le dije: &#39;Realmente no puedo hacer eso. Soy una tienda de una sola persona; no regalo amplificadores.&#39; Y él dijo: &#39;Somos los Rolling Stones, no pagamos por los amplificadores.&#39;&quot;</em></p><p>Durante este breve estancamiento, Smith podía escuchar a Keith Richards de fondo, susurrando qué decirle a Stewart. Smith pidió hablar directamente con Richards.</p><p><em>&quot;Keith se pone al teléfono y es simplemente el mejor, un tipo súper amigable,&quot;</em> señaló Smith. <em>&quot;Me dice: &#39;Oye, hombre. ¿Cómo estás? Sí, me encantaría poner mis manos en uno de tus amplificadores.&#39; Pasamos por lo mismo y él dijo: &#39;Bueno, simplemente no parece correcto. No hemos pagado por equipo en una eternidad. Simplemente no lo hacemos.&#39; Le dije: &#39;Bueno, yo simplemente no regalo el equipo porque básicamente soy solo un gato hambriento aquí...&#39;&quot;</em></p><p>Smith, asumiendo un riesgo enorme con una de las bandas de rock más grandes del planeta, hizo una propuesta audaz: Los Stones deberían comprar el amplificador. Si no les gustaba, podían devolverlo para obtener un reembolso completo. O mejor aún, debido a que había una lista de espera masiva por los Boogies, simplemente podían venderlo por una ganancia si no era para ellos.</p><p>Después de una larga pausa embarazosa, Richards respondió: <em>&quot;Bueno, sí, amigo. Esa sería una muy buena idea, excepto que ya sé que quiero el amplificador. No hay duda de eso. Jugué con el de Santana cuando él tocó con nosotros. Y no quiero solo uno, quiero seis de ellos.&quot;</em></p><h2 id="el-mark-i-llega-al-escenario-y-al-estudio" tabindex="-1">El Mark I Llega al Escenario y al Estudio <a class="header-anchor" href="#el-mark-i-llega-al-escenario-y-al-estudio" aria-label="Permalink to &quot;El Mark I Llega al Escenario y al Estudio&quot;">​</a></h2><p>Esos primeros seis amplificadores Mesa/Boogie Mark I, con el ecualizador gráfico de 5 bandas y altavoces de alto headroom, se convirtieron en la piedra angular del sonido de la guitarra de los Stones durante la siguiente media década.</p><p>Las fotografías de los shows de El Mocambo en marzo de 1977 muestran claramente a Richards (y a Ronnie Wood) tocando sus nuevos Boogies de madera dura. El amplificador de Richards adquirió famosamente una quemadura de cigarrillo justo encima de la perilla de agudos (Treble) durante estos mismos conciertos.</p><p>Estos amplificadores fueron empacados y enviados a los <em>Pathé Marconi Studios</em> en París para las legendarias sesiones de <em>Some Girls</em> más tarde ese año. El tremendo rango dinámico y el ataque articulado de la sección de potencia de 100W 6L6, combinado con la precisión del ecualizador gráfico, permitió a Richards y Wood elaborar tonos que eran contundentes y limpios, pero que conservaban un borde musculoso y arenoso, atravesando perfectamente la mezcla en pistas como &quot;Beast of Burden&quot; y &quot;Shattered&quot;.</p><p>Los Boogies siguieron siendo la línea de fondo principal de la banda durante la grabación de <em>Emotional Rescue</em> (1979-1980 en Compass Point y Pathé Marconi) y <em>Tattoo You</em> (1981). Con los años, los Rolling Stones llegarían a comprar—y pagar en su totalidad—más de 40 amplificadores Mesa/Boogie.</p><h2 id="el-fin-de-una-era-y-el-regreso-a-las-raices" tabindex="-1">El Fin de una Era y el Regreso a las Raíces <a class="header-anchor" href="#el-fin-de-una-era-y-el-regreso-a-las-raices" aria-label="Permalink to &quot;El Fin de una Era y el Regreso a las Raíces&quot;">​</a></h2><p>El Mesa/Boogie Mark I (y más tarde los modelos Mark II y III) siguieron siendo el núcleo indiscutible del equipo de guitarra de Richards durante más de una década. Impulsaron la masiva gira <em>Steel Wheels</em> en 1989 y todavía estaban muy presentes durante sus giras solistas de los <em>X-Pensive Winos</em> en 1992 y 1993. De hecho, ese Mark I original de 1977 (número de serie A804) fue enviado de regreso a la fábrica de Mesa en California para un ajuste justo antes de la gira de los Winos del &#39;92.</p><p>Sin embargo, a mediados de los 90 (<em>Voodoo Lounge</em> y <em>Bridges to Babylon</em>), Keith comenzó a hacer una transición de regreso a sus raíces. Redescubrió su amor por el crujido suelto, orgánico y sin comprimir de los amplificadores <strong>Fender Tweed</strong> de la década de 1950, específicamente los High Power Tweed Twins y los Tweed Deluxes, los cuales han permanecido como el elemento básico de su sonido en vivo y en estudio desde entonces.</p><blockquote><p>🎸 <strong>¿Buscas ese tono crudo de Tweed de los años 50?</strong><br> Si quieres experimentar la ruptura cruda y sensible al tacto de la era Tweed a la que Keith eventualmente regresó, echa un vistazo a nuestro <strong><a href="/es/midnight-rambler.html">plugin Midnight Rambler</a></strong>: una fiel emulación neuronal de un Fender Tweed Deluxe (5E3) de los años 50 al máximo de volumen.</p></blockquote><p>Hoy en día, ese Mark I original de 1977 con la quemadura de cigarrillo todavía existe, un testimonio físico de un momento crucial en el que un constructor de amplificadores boutique de California ayudó a redefinir el sonido de la banda de rock and roll más grande del mundo.</p><blockquote><p><em>Historia adaptada del artículo de Dave Hunter &quot;Keith Richards’ 1977 Mesa/Boogie Mark I&quot; de la revista Vintage Guitar®. Lee el artículo original completo <a href="https://www.vintageguitar.com/55906/keith-richards-1977-mesa-boogie-mark-i/" target="_blank" rel="noreferrer">aquí</a>.</em></p></blockquote><hr><div style="text-align:center;margin:2rem 0;"><a href="/es/tattoo-you" class="rock-btn rock-btn-primary" style="display:inline-block;padding:0.6rem 1.5rem;">← Volver al Manual de Tattoo You</a></div>',29)),a("div",c,[e[1]||(e[1]=a("div",{class:"rock-card-contact-title"},"¿Tienes fotos de archivo o historias de estudio?",-1)),e[2]||(e[2]=a("p",{class:"rock-card-contact-desc"},"Si tienes información de archivo o anécdotas sobre los equipos de estudio de los Stones de finales de los 70 y principios de los 80, nos encantaría escucharte:",-1)),a("div",m,[e[0]||(e[0]=a("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),a("button",{class:"rock-copy-btn",onClick:s},l(o.value),1)])])]))}});export{f as __pageData,y as default};
